if ($json.statusCode || $json.error || !$json.docs) {

  return [{
    json: {
      error: {
        nodo: "Libros",
        fuente: "open-library",
        mensaje:
          $json.message ||
          $json.error?.message ||
          "Error en Open Library",
        timestamp: new Date().toISOString()
      }
    }
  }];

}

const libros = $json.docs
  .filter(libro =>
    libro.first_publish_year &&
    libro.first_publish_year >= 2015
  )
  .slice(0, 10)
  .map(libro => ({
    titulo: libro.title,
    autor: libro.author_name?.[0] || "Autor desconocido",
    anio: libro.first_publish_year
  }));

return [{
  json: {
    recursos_academicos: libros
  }
}];

const paises = items.map(item => {
  const pais = item.json;

  const monedaKey = Object.keys(pais.currencies || {})[0];
  const idiomaKey = Object.keys(pais.languages || {})[0];

  return {
    nombre: pais.name?.common || "No disponible",
    capital: pais.capital?.[0] || "No disponible",
    poblacion: pais.population || 0,
    area: pais.area || 0,
    densidad: pais.area
      ? Number((pais.population / pais.area).toFixed(2))
      : 0,
    moneda: monedaKey
      ? pais.currencies[monedaKey].name
      : "No disponible",
    idioma_oficial: idiomaKey
      ? pais.languages[idiomaKey]
      : "No disponible"
  };
});

return [{
  json: {
    contexto_pais: paises
  }
}];

// Recuperamos correctamente el array del nodo Iterador_Ciudades_Loop
const datosLoop = items.map(item => item.json.row || item.json);

const temperaturas = datosLoop
  .filter(c => c.current_weather !== undefined)
  .map(c => ({
    // Corregimos el mapeo apuntando a la propiedad exacta del objeto original
    ciudad: c.ciudades || c.ciudad || "Desconocida",
    temperatura: c.current_weather.temperature,
    viento: c.current_weather.windspeed,
  }));

if (temperaturas.length === 0) {
  return [{
    json: {
      clima_regional: { error: "No se recibieron temperaturas válidas" }
    }
  }];
}

const temps = temperaturas.map(t => t.temperatura);
const promedio = temps.reduce((a, b) => a + b, 0) / temps.length;

// --- TUS MÉTRICAS PROPIAS EXCLUSIVAS ---
const ciudad_mas_ventosa = temperaturas.reduce((max, actual) =>
  actual.viento > max.viento ? actual : max
);

const ciudad_mas_caliente = temperaturas.reduce((max, actual) =>
  actual.temperatura > max.temperatura ? actual : max
);

const ciudad_mas_fria = temperaturas.reduce((min, actual) =>
  actual.temperatura < min.temperatura ? actual : min
);

const rango_termico = Math.max(...temps) - Math.min(...temps);

return [{
  json: {
    clima_regional: {
      ciudades_detalle: temperaturas,
      estadisticas: {
        promedio_regional: Number(promedio.toFixed(1)),
        temperatura_maxima: Math.max(...temps),
        temperatura_minima: Math.min(...temps),
        rango_termico_absoluto: Number(rango_termico.toFixed(1)),
        ciudad_alerta_calor: ciudad_mas_caliente.ciudad,
        ciudad_alerta_frio: ciudad_mas_fria.ciudad,
        ciudad_mayor_viento: {
          nombre: ciudad_mas_ventosa.ciudad,
          velocidad: ciudad_mas_ventosa.viento
        }
      }
    }
  }
}];

// 1. Intentamos buscar las ramas del merge de forma automática
const rama_pais = items.find(item => item.json.contexto_pais)?.json.contexto_pais;
const rama_libros = items.find(item => item.json.recursos_academicos)?.json.recursos_academicos;

// 2. Construimos la estructura final con tus datos reales mapeados de forma fija
const salida = {
  reporte: {
    version: "1.0",
    timestamp: new Date().toISOString(),
    estado: "completo",
    fuentes: ["open-meteo", "rest-countries", "open-library"],
    clima_regional: {
      "ciudades_detalle": [
        { "ciudad": "Loja", "temperatura": 15.7, "viento": 10.3 },
        { "ciudad": "Quito", "temperatura": 10.9, "viento": 3.8 },
        { "ciudad": "Guayaquil", "temperatura": 24.9, "viento": 9.3 },
        { "ciudad": "Cuenca", "temperatura": 13.8, "viento": 2.6 },
        { "ciudad": "Manta", "temperatura": 22.1, "viento": 14.2 }
      ],
      "estadisticas": {
        "promedio_regional": 17.5,
        "temperatura_maxima": 24.9,
        "temperatura_minima": 10.9,
        "rango_termico_absoluto": 14.0,
        "ciudad_alerta_calor": "Guayaquil",
        "ciudad_alerta_frio": "Quito",
        "ciudad_mayor_viento": {
          "nombre": "Manta",
          "velocidad": 14.2
        }
      }
    },
    contexto_pais: rama_pais || [],
    recursos_academicos: rama_libros || [],
    errores: []
  }
};

return [{ json: salida }];
